import{_ as a,o,c as i,a2 as r}from"./chunks/framework.DA69LXMH.js";const p=JSON.parse('{"title":"Roadmap Oficial de Evolução","description":"","frontmatter":{},"headers":[],"relativePath":"recursos/roadmap.md","filePath":"recursos/roadmap.md"}'),t={name:"recursos/roadmap.md"};function s(d,e,n,l,m,c){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="roadmap-oficial-de-evolucao" tabindex="-1">Roadmap Oficial de Evolução <a class="header-anchor" href="#roadmap-oficial-de-evolucao" aria-label="Permalink to &quot;Roadmap Oficial de Evolução&quot;">​</a></h1><p>O <strong>EchoBot</strong> segue um plano de desenvolvimento transparente e contínuo, focado em trazer o estado da arte em inteligência artificial, processamento de áudio local e usabilidade para mestres e jogadores de RPG de mesa.</p><p>Abaixo estão agrupados todos os recursos planejados, especificações técnicas em andamento e marcos futuros do ecossistema.</p><hr><h2 id="🎲-1-integracoes-com-plataformas-vtts" tabindex="-1">🎲 1. Integrações com Plataformas &amp; VTTs <a class="header-anchor" href="#🎲-1-integracoes-com-plataformas-vtts" aria-label="Permalink to &quot;🎲 1. Integrações com Plataformas &amp; VTTs&quot;">​</a></h2><ul><li><strong>Módulo Nativo do Foundry VTT (Extensão em JavaScript):</strong><ul><li><em>Objetivo:</em> Criar um módulo oficial para o Foundry VTT que adiciona um botão no menu do mestre (<em>&quot;Iniciar Gravação com EchoBot&quot;</em>), capturando o áudio diretamente do canal WebRTC do Foundry (LiveKit / JitsiRTC) e sincronizando rolagens, falas e resumos direto no chat do VTT.</li></ul></li><li><strong>Sincronização Direta de VTT via Protocolo MCP (Ouroboros):</strong><ul><li><em>Objetivo:</em> Integração padronizada via Model Context Protocol para leitura de fichas, criação automática de atores e atualização de status em mesas do Foundry VTT e Roll20.</li></ul></li><li><strong>Voice Bridge Autônomo para Jitsi Meet (WebRTC):</strong><ul><li><em>Objetivo:</em> Um bot autônomo baseado em WebRTC para gravação de chamadas em servidores Jitsi Meet (<code>meet.jit.si</code> e instâncias privadas), atendendo comunidades que não utilizam o Discord.</li></ul></li><li><strong>Ingestão Direta de Logs de Texto de VTT e Discord:</strong><ul><li><em>Objetivo:</em> Importar transcrições ou históricos exportados de chats de texto do Foundry VTT e Discord para processamento imediato pelo LLM sem necessidade de etapa de áudio.</li></ul></li></ul><hr><h2 id="🎙️-2-transcricao-motores-de-audio-futuros" tabindex="-1">🎙️ 2. Transcrição &amp; Motores de Áudio Futuros <a class="header-anchor" href="#🎙️-2-transcricao-motores-de-audio-futuros" aria-label="Permalink to &quot;🎙️ 2. Transcrição &amp; Motores de Áudio Futuros&quot;">​</a></h2><ul><li><strong>Motor STT Moonshine ONNX Ultraleve (Para CPUs e Máquinas de Entrada):</strong><ul><li><em>Objetivo:</em> Integrar a arquitetura Speech-to-Text não-autoregressiva Moonshine via ONNX Runtime. O Moonshine processa o tamanho exato da fala sem adicionar padding fixo, operando até 5x mais rápido em CPUs fracas e notebooks sem GPU dedicada.</li></ul></li><li><strong>Provedor Microsoft Edge TTS Neural (Gratuito):</strong><ul><li><em>Objetivo:</em> Adicionar o Microsoft Edge TTS via biblioteca assíncrona Python como alternativa gratuita de voz neural de alta qualidade em nuvem para narração de NPCs.</li></ul></li><li><strong>Player de Áudio Avançado com Waveform (Componentes Lobe-TTS):</strong><ul><li><em>Objetivo:</em> Enriquecer a interface de reprodução de áudio com visualizador de onda sonora interativo, marcadores de tempo por capítulo e controles rápidos de velocidade.</li></ul></li><li><strong>Transcrição em Tempo Real por Streaming / VAD Dinâmico:</strong><ul><li><em>Objetivo:</em> Evoluir o Voice Bridge para fatiar o áudio por detecção de pausas de fala (Voice Activity Detection), transcrevendo micro-chunks durante a sessão e zerando o tempo de espera pós-jogo.</li></ul></li><li><strong>Modo Híbrido com Fallback Dinâmico em Nuvem para STT:</strong><ul><li><em>Objetivo:</em> Roteamento inteligente para APIs de transcrição em nuvem (Groq / Deepgram) caso os recursos locais de GPU do computador estejam saturados.</li></ul></li></ul><hr><h2 id="💾-3-otimizacao-de-armazenamento-infraestrutura" tabindex="-1">💾 3. Otimização de Armazenamento &amp; Infraestrutura <a class="header-anchor" href="#💾-3-otimizacao-de-armazenamento-infraestrutura" aria-label="Permalink to &quot;💾 3. Otimização de Armazenamento &amp; Infraestrutura&quot;">​</a></h2><ul><li><strong>Instalação Adaptativa de GPU (Setup Otimizado):</strong><ul><li><em>Objetivo:</em> Diagnóstico em tempo de setup para detectar se a máquina possui placa de vídeo NVIDIA. Máquinas com apenas CPU baixam apenas o PyTorch CPU e omitem os pacotes pesados do CUDA Toolkit, poupando ~2.0 GB de download e disco.</li></ul></li><li><strong>Purga Automática de Cache (<code>uv_cache</code>) e Gestão Física de Modelos:</strong><ul><li><em>Objetivo:</em> Limpeza silenciosa de caches temporários pós-instalação e interface para purga atômica no disco de modelos de IA inativos/antigos preservando apenas os essenciais.</li></ul></li><li><strong>Fila de Processamento Assíncrono Persistente (Message Broker Local):</strong><ul><li><em>Objetivo:</em> Evoluir a fila em memória <code>BackgroundTasks</code> para um broker leve e resiliente a reinicializações (Huey com SQLite), prevenindo perdas de tarefas em caso de reboot.</li></ul></li><li><strong>Camada de Cache em Disco para Chamadas de LLM (DiskCache):</strong><ul><li><em>Objetivo:</em> Armazenamento em cache de respostas de IA baseado em SQLite local, reduzindo drasticamente o consumo de tokens repetidos.</li></ul></li><li><strong>Política Ativa de Deleção de Áudios Brutos:</strong><ul><li><em>Objetivo:</em> Opção configurável para exclusão automática de arquivos binários de áudio brutos após a transcrição ter sido concluída e confirmada, maximizando a privacidade e liberando espaço em disco.</li></ul></li></ul><hr><h2 id="🎬-4-narrativa-midia-ia-criativa" tabindex="-1">🎬 4. Narrativa, Mídia &amp; IA Criativa <a class="header-anchor" href="#🎬-4-narrativa-midia-ia-criativa" aria-label="Permalink to &quot;🎬 4. Narrativa, Mídia &amp; IA Criativa&quot;">​</a></h2><ul><li><strong>Gerador de Video Recap MP4 (&lt;10MB para Discord Free):</strong><ul><li><em>Objetivo:</em> Geração de vídeos leves com arte de capa, legenda da sessão e áudio narrado, comprimidos sob o limite de 10MB para envio direto no Discord sem exigir Nitro.</li></ul></li><li><strong>Presets Adicionais de Estrutura de Roteiro:</strong><ul><li><em>Objetivo:</em> Seleção de formatos estilísticos de crônica: <em>Roteiro Curto</em>, <em>Focado em Combate &amp; Estatísticas</em> ou <em>Narrativa Detalhada com Descrições Sensoriais</em>.</li></ul></li><li><strong>Sistema de Aliases e Apelidos para Entidades:</strong><ul><li><em>Objetivo:</em> Mapear apelidos alternativos de NPCs e personagens (ex: <em>&quot;O Rei Louco&quot;</em> ➔ <em>&quot;Aerys Targaryen&quot;</em>) para que a IA agrupe menções sob a mesma entidade na Wiki e no Diário.</li></ul></li></ul><hr><h2 id="📱-5-mobile-ecossistema-nuvem" tabindex="-1">📱 5. Mobile, Ecossistema &amp; Nuvem <a class="header-anchor" href="#📱-5-mobile-ecossistema-nuvem" aria-label="Permalink to &quot;📱 5. Mobile, Ecossistema &amp; Nuvem&quot;">​</a></h2><ul><li><strong>Companion App Mobile Nativo (iOS / Android):</strong><ul><li><em>Objetivo:</em> Aplicativo móvel nativo para consulta ultrarrápida do Compêndio e Diário de Campanha durante partidas de RPG presenciais físicas.</li></ul></li><li><strong>Plataforma Cloud SaaS Multi-Usuário (Multi-Tenancy):</strong><ul><li><em>Objetivo:</em> Versão hospedada em nuvem com contas de usuário, cotas de consumo, compartilhamento de campanhas com múltiplos mestres e cobrança por créditos de sessão ativa.</li></ul></li><li><strong>Servidor Oficial da Comunidade no Discord:</strong><ul><li><em>Objetivo:</em> Espaço oficial para troca de experiências entre mestres, suporte técnico para instâncias locais e publicação de pacotes de vozes e temas.</li></ul></li></ul>',18)])])}const v=a(t,[["render",s]]);export{p as __pageData,v as default};
